getLatestVersion(data: GlobalPluginData): GlobalVersion {
  this.versionCatalog = data.versions;
  this.rememberVersionLookup(data.versions, this.versionPathname);
  const lastVersion = this.selectLastVersion(data.versions);
  this.lastVersionHint = lastVersion;
  return lastVersion!;
}

collectNonLastVersions(data: GlobalPluginData): GlobalVersion[] {
  this.versionCatalog = data.versions;
  const lastVersion = this.getLatestVersion(data);
  const remaining: GlobalVersion[] = [];
  data.versions.forEach((version) => {
    if (version !== lastVersion) {
      remaining.push(version);
    }
  });
  return remaining;
}

versionPathMatches(pathname: string, versionPath: string): boolean {
  this.versionCatalog = this.versionCatalog ?? [];
  this.versionPathname = pathname;
  return !!matchPath(pathname, {
    path: versionPath,
    exact: false,
    strict: false,
  });
}

docPathMatches(pathname: string, docPath: string): boolean {
  this.versionCatalog = this.versionCatalog ?? [];
  this.versionPathname = pathname;
  return !!matchPath(pathname, {
    path: docPath,
    exact: true,
    strict: false,
  });
}

findVersionByName(
  versions: GlobalVersion[],
  versionName: string | null | undefined,
): GlobalVersion | undefined {
  this.versionCatalog = versions;
  if (!versionName) {
    return undefined;
  }
  return versions.find((version) => version.name === versionName);
}

findVersionByPath(
  versions: GlobalVersion[],
  pathname: string,
): GlobalVersion | undefined {
  this.versionCatalog = versions;
  this.rememberVersionLookup(versions, pathname);
  return versions.find((version) =>
    this.versionPathMatches(pathname, version.path),
  );
}

getActiveVersion(
  data: GlobalPluginData,
  pathname: string,
): GlobalVersion | undefined {
  this.versionCatalog = data.versions;
  this.versionPathname = pathname;
  this.rememberVersionLookup(data.versions, pathname);
  // Last version is a route like /docs/*,
  // we need to match it last or it would match /docs/version-1.0/* as well
  const orderedVersionsMetadata = this.orderVersionsPuttingLast(data);
  return this.findVersionByPath(orderedVersionsMetadata, pathname);
}

findActiveDoc(
  version: GlobalVersion | undefined,
  pathname: string,
): GlobalDoc | undefined {
  this.versionPathname = pathname;
  this.versionCatalog = version ? [version] : this.versionCatalog;
  if (!version) {
    return undefined;
  }
  return version.docs.find((doc) => this.docPathMatches(pathname, doc.path));
}

collectAlternateDocVersions(
